def roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []
    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())
    fe_candidates += [cwd, cwd / "LambdaVisionSuper", cwd.parent / "LambdaVisionSuper"]
    be_candidates += [cwd, cwd / "LambdaVisionSuperBackEnd", cwd.parent / "LambdaVisionSuperBackEnd"]
    frontend = next((p for p in fe_candidates if (p / "src/Pages/ComputerVisionPage.tsx").exists()), None)
    backend = next((p for p in be_candidates if (p / "app/services/vision_app/automation_manager.py").exists()), None)
    if frontend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuper frontend")
    if backend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd")
    return frontend, backend


def three_way(current: str, old: str, new: str):
    if current == new:
        return "OK", current
    if current == old:
        return "UPDATE", new
    with tempfile.TemporaryDirectory(prefix="lambda_v1420_") as td:
        td = Path(td)
        a, b, c = td / "current", td / "base", td / "desired"
        a.write_text(current, encoding="utf-8")
        b.write_text(old, encoding="utf-8")
        c.write_text(new, encoding="utf-8")
        proc = subprocess.run(["git", "merge-file", "-p", "--diff3", str(a), str(b), str(c)], text=True, capture_output=True)
        if proc.returncode == 0:
            return "MERGE", proc.stdout
        return "CONFLICT", proc.stdout


def replace_soft_config(text: str) -> str:
    if 'backpressure_policy: Literal["skip", "latest", "fifo"]' in text:
        return text
    pattern = r'class SoftTriggerConfig\(BaseModel\):.*?\n\nclass WorkspaceDefinition\(BaseModel\):'
    match = re.search(pattern, text, flags=re.S)
    if not match:
        raise RuntimeError("SoftTriggerConfig block not found")
    block = '''class SoftTriggerConfig(BaseModel):
    # Streaming-frame trigger owned by one inspection Workspace.
    enabled: bool = False
    roi: NormalizedRect | None = None
    threshold_mode: Literal["bright", "dark"] = "bright"
    pixel_threshold: int = Field(default=80, ge=0, le=255)
    trigger_pixel_count: int = Field(default=100, ge=1)
    reset_pixel_count: int = Field(default=20, ge=0)
    frame_stride: int = Field(default=1, ge=1, le=120)
    cooldown_ms: int = Field(default=500, ge=0, le=120000)
    snapshot_to_image_slot: bool = True
    run_inspection: bool = True
    backpressure_policy: Literal["skip", "latest", "fifo"] = "skip"
    queue_capacity: int = Field(default=3, ge=1, le=128)
    overflow_policy: Literal["drop_oldest", "drop_newest"] = "drop_oldest"


class WorkspaceDefinition(BaseModel):'''
    return text[:match.start()] + block + text[match.end():]


def patch_manager(text: str) -> str:
    if "_queue_soft_trigger_locked" in text and "_soft_dispatch_queue" in text:
        return text
    if "from time import monotonic, perf_counter, sleep" not in text:
        text = text.replace("from time import monotonic, perf_counter", "from time import monotonic, perf_counter, sleep", 1)
    anchor = "        self._lock = RLock()\n"
    if anchor not in text:
        raise RuntimeError("AutomationManager __init__ lock anchor not found")
    text = text.replace(anchor, '''        self._lock = RLock()
        # v0.14.2: Program-level serialized inspection dispatcher.
        self._soft_dispatch_lock = RLock()
        self._soft_dispatch_busy: set[str] = set()
        self._soft_dispatch_queue: dict[str, deque[dict[str, Any]]] = defaultdict(deque)
        self._soft_delivery: dict[tuple[str, str], dict[str, Any]] = {}
''', 1)
    pattern = r'    def _on_soft_trigger\(.*?\n    def _append_trace'
    match = re.search(pattern, text, flags=re.S)
    if not match:
        raise RuntimeError("AutomationManager _on_soft_trigger block not found")
    text = text[:match.start()] + MANAGER_METHODS + '    def _append_trace' + text[match.end():]
    if "self._clear_soft_dispatch(program_id)" not in text:
        needle = "        self.streaming.disarm_program(program)\n        state = self.stop(program_id)"
        if needle not in text:
            raise RuntimeError("AutomationManager offline() anchor not found")
        text = text.replace(needle, "        self.streaming.disarm_program(program)\n        self._clear_soft_dispatch(program_id)\n        state = self.stop(program_id)", 1)
    return text


def patch_registry(text: str) -> str:
    if 'path=f"{soft_root}.queue_depth"' in text:
        return text
    fires = re.search(r'(?P<indent>[ \t]*)specs\.append\(EndpointSpec\(path=f"\{soft_root\}\.fires".*?\)\)\n', text)
    if not fires:
        raise RuntimeError("EndpointRegistry Soft Trigger fires anchor not found")
    indent = fires.group("indent")
    lines = [
        'specs.append(EndpointSpec(path=f"{soft_root}.backpressure_policy", kind="state", data_type="string", description="Configured busy-frame policy", source=soft_root, last_value=getattr(workspace.soft_trigger, "backpressure_policy", "skip"), allowed_values=["skip", "latest", "fifo"]))',
        'specs.append(EndpointSpec(path=f"{soft_root}.queue_capacity", kind="state", data_type="integer", description="Configured FIFO cache capacity", source=soft_root, last_value=getattr(workspace.soft_trigger, "queue_capacity", 3)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.inspection_busy", kind="state", data_type="bool", description="Program inspection dispatcher is busy", source=soft_root, last_value=bool(soft_state.get("inspection_busy", False)), allowed_values=["ON", "OFF"]))',
        'specs.append(EndpointSpec(path=f"{soft_root}.queue_depth", kind="state", data_type="integer", description="Waiting Soft Trigger frames", source=soft_root, last_value=soft_state.get("queue_depth", 0)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.processed_total", kind="state", data_type="integer", description="Soft Trigger frames processed by inspection", source=soft_root, last_value=soft_state.get("processed_total", 0)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.skipped_busy", kind="state", data_type="integer", description="Triggers skipped because inspection was busy", source=soft_root, last_value=soft_state.get("skipped_busy", 0)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.dropped_overflow", kind="state", data_type="integer", description="Frames dropped by queue overflow", source=soft_root, last_value=soft_state.get("dropped_overflow", 0)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.replaced_latest", kind="state", data_type="integer", description="Waiting frames replaced by Keep latest policy", source=soft_root, last_value=soft_state.get("replaced_latest", 0)))',
        'specs.append(EndpointSpec(path=f"{soft_root}.avg_queue_wait_ms", kind="state", data_type="number", description="Average queue wait before inspection", source=soft_root, last_value=soft_state.get("avg_queue_wait_ms", 0.0), unit="ms"))',
        'specs.append(EndpointSpec(path=f"{soft_root}.last_processing_ms", kind="state", data_type="number", description="Last Soft Trigger inspection processing time", source=soft_root, last_value=soft_state.get("last_processing_ms", 0.0), unit="ms"))',
        'specs.append(EndpointSpec(path=f"{soft_root}.last_action", kind="state", data_type="string", description="Last backpressure/dispatcher action", source=soft_root, last_value=soft_state.get("last_action", "")))',
    ]
    extra = "".join(indent + line + "\n" for line in lines)
    text = text[:fires.end()] + extra + text[fires.end():]
    event_anchor = 'specs.append(EndpointSpec(path=f"{root}.soft_triggered", kind="event", description="Soft Trigger threshold crossed", source=root))'
    if event_anchor not in text:
        raise RuntimeError("EndpointRegistry soft_triggered event anchor not found")
    events = event_anchor + '''
            specs.append(EndpointSpec(path=f"{root}.soft_trigger_queued", kind="event", description="Soft Trigger frame queued while inspection is busy", source=root))
            specs.append(EndpointSpec(path=f"{root}.soft_trigger_skipped", kind="event", description="Soft Trigger frame skipped by busy policy", source=root))
            specs.append(EndpointSpec(path=f"{root}.soft_trigger_overflow", kind="event", description="Soft Trigger queue overflow dropped a frame", source=root))
            specs.append(EndpointSpec(path=f"{root}.soft_trigger_dispatched", kind="event", description="Soft Trigger frame started inspection", source=root))'''
    return text.replace(event_anchor, events, 1)


def patch_api_py(text: str) -> str:
    if "/soft-trigger/preview" in text:
        return text
    if "SoftTriggerConfig" not in text:
        raise RuntimeError("vision_app_api.py does not import SoftTriggerConfig")
    route = r'''

@router.post("/programs/{program_id}/workspaces/{workspace_alias}/soft-trigger/preview", summary="Render exact Soft Trigger threshold debug frame")
def workspace_soft_trigger_preview(program_id: str, workspace_alias: str, config: SoftTriggerConfig, mode: str = "overlay", after_sequence: int = 0, quality: int = 82):
    try:
        program = repository.get(program_id)
        workspace = workspace_by_alias(program, workspace_alias)
        alias = safe_alias(workspace.alias, workspace.workspace_id)
        _image, sequence = automation_manager.streaming.latest_frame(program_id, alias)
        if int(sequence) <= int(after_sequence):
            return Response(status_code=204, headers={"X-Frame-Sequence": str(sequence)})
        payload, sequence = automation_manager.streaming.preview_jpeg(program_id, alias, config, mode=mode, quality=quality)
        return Response(content=payload, media_type="image/jpeg", headers={"X-Frame-Sequence": str(sequence), "Cache-Control": "no-store"})
    except Exception as exc:
        raise _error(exc)
'''
    return text + route


def patch_ts_api(text: str) -> str:
    soft_cfg = re.search(r'export interface SoftTriggerConfig \{.*?\n\}', text, flags=re.S)
    if not soft_cfg:
        raise RuntimeError("SoftTriggerConfig TS interface not found")
    cfg = '''export interface SoftTriggerConfig {
  enabled:boolean; roi:NormalizedRect|null; threshold_mode:'bright'|'dark'; pixel_threshold:number;
  trigger_pixel_count:number; reset_pixel_count:number; frame_stride:number; cooldown_ms:number;
  snapshot_to_image_slot:boolean; run_inspection:boolean;
  backpressure_policy:'skip'|'latest'|'fifo'; queue_capacity:number; overflow_policy:'drop_oldest'|'drop_newest';
}'''
    text = text[:soft_cfg.start()] + cfg + text[soft_cfg.end():]
    runtime = re.search(r'export interface SoftTriggerRuntimeStatus \{.*?\n\}', text, flags=re.S)
    if not runtime:
        raise RuntimeError("SoftTriggerRuntimeStatus TS interface not found")
    rt = '''export interface SoftTriggerRuntimeStatus {
  workspace:string; camera:string; enabled:boolean; armed:boolean; pixel_count:number; active_ratio:number; roi_pixels:number;
  fires:number; last_fire_sequence:number; last_error:string;
  inspection_busy?:boolean; queue_depth?:number; queue_capacity?:number; triggered_total?:number; accepted_total?:number;
  queued_total?:number; processed_total?:number; skipped_busy?:number; dropped_overflow?:number; replaced_latest?:number;
  failed_total?:number; max_queue_depth?:number; last_queue_wait_ms?:number; avg_queue_wait_ms?:number;
  last_processing_ms?:number; last_action?:string;
}'''
    text = text[:runtime.start()] + rt + text[runtime.end():]
    text = re.sub(r'export interface StreamingStatusResponse \{[^\n]*\}', 'export interface StreamingStatusResponse { success:boolean; stream:CameraStreamStatus; soft_trigger:SoftTriggerRuntimeStatus|null; }', text, count=1)
    if "softTriggerPreview:" not in text:
        anchor = re.search(r'(\s+analyzeSoftTrigger: async .*?\n)', text)
        if not anchor:
            raise RuntimeError("analyzeSoftTrigger API anchor not found")
        method = '''  softTriggerPreview: async (id:string,workspaceAlias:string,config:SoftTriggerConfig,mode:'raw'|'gray'|'mask'|'overlay',afterSequence=0):Promise<{blob:Blob|null;sequence:number}> => {
    const r=await axiosClient.post(`${api_version}/computer-vision/programs/${encodeURIComponent(id)}/workspaces/${encodeURIComponent(workspaceAlias)}/soft-trigger/preview`,config,{params:{mode,after_sequence:afterSequence},responseType:'blob',validateStatus:(s:number)=>s===200||s===204});
    return {blob:r.status===204?null:r.data,sequence:Number(r.headers?.['x-frame-sequence']??afterSequence)};
  },
'''
        text = text[:anchor.end()] + method + text[anchor.end():]
    return text


def patch_page(text: str) -> str:
    text = re.sub(r"\{key:'streaming',label:'Streaming'(?:,icon:[A-Za-z0-9_]+)?\}", "{key:'streaming',label:'Streaming',icon:Activity}", text, count=1)
    lucide = re.search(r"import \{([^}]*)\} from 'lucide-react';", text)
    if not lucide:
        raise RuntimeError("lucide-react import not found")
    names = [part.strip() for part in lucide.group(1).split(",") if part.strip()]
    if "Activity" not in names:
        names.insert(0, "Activity")
        replacement = "import { " + ", ".join(names) + " } from 'lucide-react';"
        text = text[:lucide.start()] + replacement + text[lucide.end():]
    if "backpressure_policy:'skip'" not in text:
        needle = "snapshot_to_image_slot:true,run_inspection:true}"
        if needle in text:
            text = text.replace(needle, "snapshot_to_image_slot:true,run_inspection:true,backpressure_policy:'skip',queue_capacity:3,overflow_policy:'drop_oldest'}", 1)
    text = re.sub(r"Vision App v0\.14\.[0-9]+", "Vision App v0.14.2", text)
    return text


