def rp(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    return backend / virtual[len("backend/"):]


def transform(frontend: Path, backend: Path, virtual: str):
    path = rp(frontend, backend, virtual)
    if not path.exists():
        return "MISSING", None, "file missing"
    current = path.read_text(encoding="utf-8")
    try:
        if virtual in EXACT:
            old, new = EXACT[virtual]
            state, merged = three_way(current, old, new)
            return state, merged, ""
        new = SEMANTIC[virtual](current)
        return ("OK" if new == current else "PATCH"), new, ""
    except Exception as exc:
        return "CONFLICT", None, str(exc)


def scan(frontend: Path, backend: Path):
    print("=" * 116)
    print("COMPUTER VISION V0.14.2 — SOFT TRIGGER TUNING / BACKPRESSURE")
    print("=" * 116)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()
    blockers = 0
    for virtual in [*SEMANTIC, *EXACT]:
        state, _, detail = transform(frontend, backend, virtual)
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            blockers += 1
            if detail:
                print(f"                 {detail}")
    for virtual, desired in CREATED.items():
        path = rp(frontend, backend, virtual)
        state = "CREATE" if not path.exists() else "OK" if path.read_text(encoding="utf-8") == desired else "CONFLICT"
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            blockers += 1
    print()
    print("v0.14.2:")
    print("  Raw / Gray / Threshold / Overlay preview uses exact backend threshold logic")
    print("  Streaming module icon explicitly uses Activity")
    print("  Busy policy: skip | latest | fifo")
    print("  FIFO overflow: drop_oldest | drop_newest")
    print("  Program-level dispatcher serializes Soft Trigger inspections")
    print("  Queue/drop/wait/processing telemetry is visible in UI and Automation IDE")
    print("  Debug JPEG work remains lazy and only runs while Streaming preview is open")
    if blockers:
        print(f"[WARN] {blockers} blocker(s). Do not apply.")
        return 1
    print("[OK] Safe to apply.")
    return 0


def regenerate(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    cmd = [sys.executable, str(generator), "--frontend", str(frontend), "--backend", str(backend)]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd += ["--output-dir", str(frontend / "docs/llm_context")]
    proc = subprocess.run(cmd, cwd=str(frontend), text=True, capture_output=True)
    if proc.returncode != 0:
        raise RuntimeError((proc.stdout + "\n" + proc.stderr).strip())
    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    if scan(frontend, backend):
        raise RuntimeError("Preflight failed")
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = frontend / ".lambda_updater_backups" / f"computer_vision_v1420_{stamp}"
    for virtual in [*SEMANTIC, *EXACT, *CREATED]:
        src = rp(frontend, backend, virtual)
        if src.exists():
            dst = backup / virtual
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    for virtual in [*SEMANTIC, *EXACT]:
        state, new, detail = transform(frontend, backend, virtual)
        if state in {"PATCH", "UPDATE", "MERGE"}:
            rp(frontend, backend, virtual).write_text(new, encoding="utf-8")
            print(f"[{state:6}] {virtual}")
        elif state == "OK":
            print(f"[KEEP  ] {virtual}")
        else:
            raise RuntimeError(f"{virtual}: {state} {detail}")
    for virtual, desired in CREATED.items():
        path = rp(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            path.write_text(desired, encoding="utf-8")
            print(f"[CREATE] {virtual}")
    print("[INFO] Regenerating LLM context docs...")
    regenerate(frontend, backend)
    print(f"[OK] Backup: {backup}")
    print("Run verify next.")
    return 0


def ts_transpile(frontend: Path):
    files = [frontend / "src/api/visionAppApi.ts", frontend / "src/Pages/ComputerVisionPage.tsx", frontend / "src/components/ComputerVision/StreamingWorkspace.tsx"]
    code = r'''const fs=require('fs'),ts=require('typescript');
let bad=false;
for(const f of process.argv.slice(1)){
 const r=ts.transpileModule(fs.readFileSync(f,'utf8'),{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});
 const e=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);
 if(e.length){bad=true;console.error('TS_ERROR',f);for(const d of e)console.error(ts.flattenDiagnosticMessageText(d.messageText,'\n'));}
}
process.exit(bad?1:0);'''
    env = dict(os.environ)
    npm_root = subprocess.run(["npm", "root", "-g"], text=True, capture_output=True)
    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (os.pathsep + env["NODE_PATH"] if env.get("NODE_PATH") else "")
    return subprocess.run(["node", "-e", code, *map(str, files)], cwd=str(frontend), env=env, text=True, capture_output=True)


def verify(frontend: Path, backend: Path, skip_build: bool = False):
    print("=" * 116)
    print("VERIFY COMPUTER VISION V0.14.2")
    print("=" * 116)
    failures = 0
    py_files = [backend / "app/services/vision_app/models.py", backend / "app/services/vision_app/automation_manager.py", backend / "app/services/vision_app/endpoint_registry.py", backend / "app/services/vision_app/streaming_runtime.py", backend / "app/api/v1/endpoints/vision_app_api.py", backend / "tests/vision_app/test_vision_app_v1420.py", frontend / "tools/generate_llm_context_map.py"]
    for path in py_files:
        try:
            py_compile.compile(str(path), doraise=True)
        except Exception as exc:
            print(f"[FAIL] Python syntax {path}: {exc}")
            failures += 1
    if failures == 0:
        print("[OK] Python syntax")
    model = (backend / "app/services/vision_app/models.py").read_text(encoding="utf-8")
    manager = (backend / "app/services/vision_app/automation_manager.py").read_text(encoding="utf-8")
    registry = (backend / "app/services/vision_app/endpoint_registry.py").read_text(encoding="utf-8")
    stream = (backend / "app/services/vision_app/streaming_runtime.py").read_text(encoding="utf-8")
    api = (backend / "app/api/v1/endpoints/vision_app_api.py").read_text(encoding="utf-8")
    page = (frontend / "src/Pages/ComputerVisionPage.tsx").read_text(encoding="utf-8")
    ui = (frontend / "src/components/ComputerVision/StreamingWorkspace.tsx").read_text(encoding="utf-8")
    ts_api = (frontend / "src/api/visionAppApi.ts").read_text(encoding="utf-8")
    checks = [
        ("Backpressure schema", 'backpressure_policy: Literal["skip", "latest", "fifo"]' in model),
        ("Serialized Soft Trigger dispatcher", "_soft_dispatch_queue" in manager and "_queue_soft_trigger_locked" in manager),
        ("Exact threshold debug renderer", "render_threshold_preview" in stream and "preview_jpeg" in stream),
        ("Threshold preview API", "/soft-trigger/preview" in api and "softTriggerPreview:" in ts_api),
        ("Streaming icon", "key:'streaming',label:'Streaming',icon:Activity" in page),
        ("Four viewport modes", "['raw','gray','mask','overlay']" in ui),
        ("Backpressure UI", "BACKPRESSURE / BUSY POLICY" in ui and "QUEUE PRESSURE" in ui),
        ("Endpoint telemetry", 'path=f"{soft_root}.queue_depth"' in registry and "skipped_busy" in registry),
        ("Regression test", (backend / "tests/vision_app/test_vision_app_v1420.py").exists()),
    ]
    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        if not ok:
            failures += 1
    if importlib.util.find_spec("pytest") is not None and (backend / "tests/vision_app").exists():
        full_ready = (backend / "app/core").exists() and (backend / "app/services/vision_app/runtime.py").exists()
        if full_ready:
            env = dict(os.environ)
            env["PYTHONPATH"] = str(backend) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
            proc = subprocess.run([sys.executable, "-m", "pytest", "-q", "tests/vision_app"], cwd=str(backend), env=env, text=True, capture_output=True)
            if proc.returncode == 0:
                print("[OK] Vision App regression tests")
                if proc.stdout.strip(): print(proc.stdout.strip())
            else:
                print("[FAIL] Vision App regression tests")
                print((proc.stdout + "\n" + proc.stderr).strip())
                failures += 1
        else:
            print("[SKIP] Full Vision App pytest unavailable in partial/mock tree")
    ts = ts_transpile(frontend)
    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    else:
        out = (ts.stdout + "\n" + ts.stderr).strip()
        if "MODULE_NOT_FOUND" in out or "Cannot find module 'typescript'" in out:
            print("[SKIP] TypeScript module unavailable")
        else:
            print("[FAIL] TypeScript syntax/transpile")
            print(out)
            failures += 1
    if not skip_build and (frontend / "node_modules").exists():
        proc = subprocess.run(["npm", "run", "build"], cwd=str(frontend))
        if proc.returncode == 0: print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    try:
        regenerate(frontend, backend)
        print("[OK] LLM context regeneration")
    except Exception as exc:
        print(f"[FAIL] Context regeneration: {exc}")
        failures += 1
    if failures:
        print(f"[FAIL] v0.14.2 verification finished with {failures} issue(s).")
        return 1
    print("[OK] Computer Vision v0.14.2 Soft Trigger tuning/backpressure verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()
    try:
        frontend, backend = roots(args.frontend, args.backend)
        if args.command == "scan": return scan(frontend, backend)
        if args.command == "apply": return apply(frontend, backend)
        return verify(frontend, backend, args.skip_build)
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
